head.b:skin:
body{margin:0;background:#ffffff;font-family:Arial,Helvetica,sans-serif;color:#222;font-size:14px;line-height:1.55}
a{color:#0645d9;text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;height:auto}
.wrap{width:980px;max-width:100%;margin:0 auto;background:#fff}
.head{background:#a40000;color:#fff;text-align:center;padding:15px 10px}
.head h1{margin:0;font-size:32px;line-height:1.05}
.head h1 a{color:#fff;text-decoration:none}
.head p{margin:4px 0 0;font-size:13px}
.nav{background:#073a8c;text-align:center;border-bottom:3px solid #ffcc00}
.nav a{display:inline-block;color:#fff;text-decoration:none;padding:8px 10px;font-size:13px;font-weight:bold}
.ticker{text-align:center;font-size:13px;padding:8px;border-bottom:1px solid #ddd}
.buttons{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin:10px 0}
.buttons a{color:#fff;text-align:center;text-decoration:none;padding:8px 5px;font-weight:bold;font-size:13px}
.buttons a:nth-child(1){background:#f97316}.buttons a:nth-child(2){background:#16a34a}.buttons a:nth-child(3){background:#2563eb}.buttons a:nth-child(4){background:#dc2626}
.buttons a:nth-child(5){background:#db2777}.buttons a:nth-child(6){background:#7c3aed}.buttons a:nth-child(7){background:#0891b2}.buttons a:nth-child(8){background:#15803d}
.adbox{background:#1f2937;color:#fff;min-height:90px;margin:10px 0;border-radius:4px;display:flex;align-items:center;justify-content:center;text-align:center;padding:16px;font-weight:bold}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:12px 0}
.box{border:1px solid #bdbdbd;background:#fff;min-height:245px}
.box h2{background:#a40000;color:#fff;font-size:16px;margin:0;padding:7px;text-align:center}
.box ul{margin:0;padding:8px 8px 8px 24px;min-height:190px}
.box li{margin:0 0 7px;font-size:13px;line-height:1.35}
.more{display:block;margin:0 8px 8px auto;width:max-content;background:#1d70b8;color:#fff!important;text-decoration:none;padding:5px 8px;border-radius:2px;font-size:12px}
.intro{margin:18px 0;font-size:14px;line-height:1.7}
.intro h2{font-size:22px;margin:14px 0 8px;color:#333}
.post-outer{border:1px solid #ddd;margin:0 0 12px;padding:12px;background:#fff}
.post-title,.post-title a{font-size:22px;color:#a40000;margin:0 0 8px;text-decoration:none}
.post-body{font-size:15px;line-height:1.7}
.post-body h2{background:#b91c1c;color:#fff;font-size:18px;margin:18px 0 8px;padding:8px 10px;border-radius:3px}
.post-body table{width:100%;border-collapse:collapse;margin:10px 0}
.post-body th,.post-body td{border:1px solid #d1d5db;padding:9px;text-align:left;vertical-align:top}
.post-body th{background:#f3f4f6}
.foot{background:#3b82f6;color:#fff;text-align:center;padding:15px;font-size:13px;margin-top:20px}
.foot a{color:#fff}
@media(max-width:760px){.wrap{width:auto;padding:0 8px}.head h1{font-size:25px}.grid{grid-template-columns:1fr}.buttons{grid-template-columns:repeat(2,1fr)}.nav a{font-size:12px;padding:8px}.post-title,.post-title a{font-size:19px}.post-body th,.post-body td{display:block;width:auto}}

body.script:
//
  (function(){
    var home = document.getElementById('homepageContent');
    var path = window.location.pathname.replace(/\/+$/, '/');
    var isHome = path === '/' || path === '/index.html';
    if (home && !isHome) {
      home.style.display = 'none';
    }
    if (!isHome) {
      var fallback = document.getElementById('postContentFallback');
      var existingBody = document.querySelector('.post-body');
      var hasRealBody = existingBody && existingBody.textContent.replace(/\s+/g,'').length > 20;
      if (fallback && !hasRealBody) {
        fallback.style.display = 'block';
        fallback.innerHTML = '<div class="post-outer"><h1 class="post-title">Loading post...</h1><div class="post-body">Please wait.</div></div>';
        fetch('/feeds/posts/default?alt=json&max-results=150')
          .then(function(response){ return response.json(); })
          .then(function(data){
            var entries = data.feed && data.feed.entry ? data.feed.entry : [];
            var current = window.location.href.split('?')[0].replace(/\/$/, '');
            var found = null;
            entries.some(function(entry){
              var links = entry.link || [];
              for (var i=0;i<links.length;i++){
                if (links[i].rel === 'alternate') {
                  var href = links[i].href.split('?')[0].replace(/\/$/, '');
                  if (href === current) {
                    found = entry;
                    return true;
                  }
                }
              }
              return false;
            });
            if (!found) {
              fallback.innerHTML = '<div class="post-outer"><h1 class="post-title">Post not found</h1><div class="post-body">Blogger feed me ye post abhi load nahi ho pa raha. Thodi der baad refresh karein.</div></div>';
              return;
            }
            var title = found.title && found.title.$t ? found.title.$t : 'Post';
            var body = found.content && found.content.$t ? found.content.$t : '';
            fallback.innerHTML = '<article class="post-outer"><h1 class="post-title">'+title+'</h1><div class="post-body">'+body+'</div></article>';
            document.title = title + ' - ' + document.title;
          })
          .catch(function(){
            fallback.innerHTML = '<div class="post-outer"><h1 class="post-title">Post loading failed</h1><div class="post-body">Feed access check karein: Blogger Settings me Site feed Allow Blog Feed = Full hona chahiye.</div></div>';
          });
      }
    }
  })();
//
